from pathlib import Path
from playwright.sync_api import sync_playwright
import json
r=Path(__file__).resolve().parent;duration=json.loads((r/'render-info.json').read_text())['duration'];times=[i/4 for i in range(int(duration*4))]
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox']);page=b.new_page(viewport={'width':1920,'height':1080});errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.goto('http://127.0.0.1:8765/practice/databricks-01/index.html');page.evaluate('document.fonts.ready');page.wait_for_function('!!window.__timelines?.main')
 bad=page.evaluate('''times=>{let bad=[];for(const t of times){window.__timelines.main.seek(t);for(const e of document.querySelectorAll('.clip')){const a=+e.dataset.start,z=a+(+e.dataset.duration);e.style.display=t>=a&&t<z?'':'none'}for(const e of document.querySelectorAll('.product,.node,.bubble,.label,.ev1-cap .w,.speaker')){if(!e.getClientRects().length)continue;let opacity=1;for(let n=e;n;n=n.parentElement)opacity*=Number(getComputedStyle(n).opacity);if(opacity<.03)continue;const q=e.getBoundingClientRect();let lim=e.closest('.stage')?[15,20,1410,966]:[10,10,1910,1070];if(q.left<lim[0]||q.top<lim[1]||q.right>lim[2]||q.bottom>lim[3])bad.push({t,text:e.textContent?.slice(0,50),rect:q.toJSON(),limit:lim});if(e.children.length===0&&(e.scrollWidth>e.clientWidth+2||e.scrollHeight>e.clientHeight+2))bad.push({t,text:e.textContent,issue:'text overflow'})}}return bad}''',times);(r/'layout-audit.json').write_text(json.dumps({'samples':len(times),'violations':bad,'page_errors':errors},indent=2));print('Layout:',len(bad),'violations',bad[:4]);assert not bad and not errors;b.close()
